// Reads the cursor from Weaviate's WorkflowState.
//
// The status is read from the RESPONSE, not from a thrown error. Code nodes
// run in n8n's task runner, so an exception crosses a process boundary to get
// here and its structured fields do not survive: a catch inspecting
// e.httpCode / e.statusCode / e.response.status found none of them, and the
// 404 of a first run went through as a failure. What does survive is what the
// helper returns, so the helper is told not to throw —
// ignoreHttpStatusErrors sets axios's validateStatus to () => true, and
// returnFullResponse yields { body, headers, statusCode, statusMessage }
// (verified in @n8n/backend-network/src/http/axios/request.ts).
//
// Before that it was 'Bearer ={{ $env.WEAVIATE_API_KEY }}' — n8n does not
// evaluate expressions inside a Code node, so Weaviate received those
// characters as the token and answered 401.
const url = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`
          + `/v1/objects/WorkflowState/3fa2478e-a528-4ca4-84e4-50bc76948667`;

const res = await this.helpers.httpRequest({
  method: 'GET',
  url,
  headers: { 'Authorization': `Bearer ${$env.WEAVIATE_API_KEY}` },
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});

// 404 is the first run and means "start from the beginning of time".
// Anything else that is not a success has to fail loudly: silently starting
// from the beginning on, say, a 401 would re-read the entire message history
// every five minutes and re-embed all of it.
if (res.statusCode === 404) {
  return [{ json: { lastTimestamp: '1970-01-01T00:00:00.000Z', firstRun: true } }];
}
if (res.statusCode < 200 || res.statusCode >= 300) {
  throw new Error(`Weaviate answered ${res.statusCode} for the sync cursor: `
                  + JSON.stringify(res.body).slice(0, 300));
}

const lastTimestamp = res.body?.properties?.value || '1970-01-01T00:00:00.000Z';
return [{ json: { lastTimestamp, firstRun: false } }];

// Aufbereitung aus PostgreSQL chat_message Zeilen
// Gruppieren nach sessionId, sortieren nach createdDate, message_index vergeben

// Which course each chatflow belongs to. Until this existed, every message
// was stamped with the installation's single course from the environment, so
// with several courses the history of one landed under another, five minutes
// at a time and without a word.
const courseOf = {};
for (const row of $('Look up the course per chatflow').all()) {
  courseOf[row.json.chatflow_id] = row.json.course_id;
}

const grouped = {};
let unplaceable = 0;

for (const item of $('Fetch new messages').all()) {
  const row = item.json;
  // A message from a chatflow this installation does not know is skipped,
  // not guessed at. A wrong course is worse than a missing message: the
  // message can be re-synced once the mapping exists, a wrong one is only
  // found by somebody reading another course's conversation.
  row.course_id = courseOf[row.chatflowid];
  if (!row.course_id) { unplaceable++; continue; }
  const sessionId = row.sessionId || '';
  if (!grouped[sessionId]) grouped[sessionId] = [];
  grouped[sessionId].push(row);
}

if (unplaceable > 0) {
  console.log(`Skipped ${unplaceable} message(s): no course for their chatflow.`);
}

const results = [];

for (const sessionId of Object.keys(grouped)) {
  // Nach createdDate aufsteigend sortieren
  const messages = grouped[sessionId].sort((a, b) =>
    new Date(a.createdDate) - new Date(b.createdDate)
  );

  const parts = sessionId.split('|');
  const userId = parts[0] || '';
  const agentIdStr = parts[2] || 'agent-01';
  const agentId = parseInt(agentIdStr.replace('agent-', '')) || 1;
  const chapter = agentId;

  messages.forEach((row, idx) => {
    let role = 'user';
    if (row.role === 'apiMessage') role = 'assistant';

    const traceId = row.id;
    const timestamp = row.createdDate
      ? new Date(row.createdDate).toISOString()
      : new Date().toISOString();

    const text = row.content || '';
    if (!text.trim()) return;

    results.push({ json: {
      // The course travels with the message. It was looked up above and then
      // left behind in the source row: the skip a few lines up made it look
      // handled, while every message that was written arrived at Weaviate
      // with no course at all.
      course_id: row.course_id,
      user_id: userId,
      session_id: sessionId,
      agent_id: agentId,
      role: role,
      text: text,
      timestamp: timestamp,
      message_index: idx,
      message_hash: `${traceId}_${idx}`,
      trace_id: traceId,
      chapter: chapter
    }});
  });
}

return results;

const WEAVIATE_URL = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const WEAVIATE_KEY = $env.WEAVIATE_API_KEY || '';
const results = [];

for (const item of $input.all()) {
  const hash = item.json.message_hash;
  // JSON.stringify, not "${hash}": the value has to arrive as a quoted
  // GraphQL string. Unquoted it is a parse error, and hand-added quotes
  // would make any hash containing one a way to rewrite the query.
  const query = `{
    Get {
      ChatHistory(where: {
        path: ["message_hash"],
        operator: Equal,
        valueText: ${JSON.stringify(String(hash ?? ''))}
      }) { message_hash }
    }
  }`;

  const raw = await this.helpers.httpRequest({
    method: 'POST',
    url: `${WEAVIATE_URL}/v1/graphql`,
    headers: {
      'Authorization': `Bearer ${WEAVIATE_KEY}`,
      'Content-Type': 'application/json'
    },
    body: { query },
    json: true
  });

  const response = typeof raw === 'string' ? JSON.parse(raw) : raw;
  results.push({ json: {
    ...item.json,
    ChatHistory: response?.data?.Get?.ChatHistory ?? []
  }});
}

return results;

